#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum NumpyDType {
    UInt8,
    UInt16,
    UInt32,
    UInt64,
    Int8,
    Int16,
    Int32,
    Int64,
    Float16,
    Float32,
    Float64,
    Complex64,
    Complex128,
}

impl NumpyDType {
    /// Returns the bit‐width of the dtype.
    pub fn dtype_size(&self) -> u16 {
        match self {
            NumpyDType::UInt8   => 8,
            NumpyDType::Int8    => 8,
            NumpyDType::UInt16  => 16,
            NumpyDType::Int16   => 16,
            NumpyDType::Float16 => 16,
            NumpyDType::UInt32  => 32,
            NumpyDType::Int32   => 32,
            NumpyDType::Float32 => 32,
            NumpyDType::UInt64  => 64,
            NumpyDType::Int64   => 64,
            NumpyDType::Float64 => 64,
            NumpyDType::Complex64  => 64,
            NumpyDType::Complex128 => 128,
        }
    }

    /// Returns the kind‐order: unsigned=0, signed=1, float=2, complex=3.
    pub fn dtype_kind_order(&self) -> u8 {
        match self {
            NumpyDType::UInt8  | NumpyDType::UInt16
            | NumpyDType::UInt32 | NumpyDType::UInt64 => 0,

            NumpyDType::Int8   | NumpyDType::Int16
            | NumpyDType::Int32  | NumpyDType::Int64 => 1,

            NumpyDType::Float16 | NumpyDType::Float32
            | NumpyDType::Float64 => 2,

            NumpyDType::Complex64 | NumpyDType::Complex128 => 3,
        }
    }

    /// Predicate: can this dtype represent the entire range of the given `i8`?
    pub fn can_represent_value(&self, v: i8) -> bool {
        match self {
            // Unsigned only if non‐negative
            NumpyDType::UInt8  | NumpyDType::UInt16
            | NumpyDType::UInt32 | NumpyDType::UInt64 => v >= 0,

            // Signed ints always cover full i8 range
            NumpyDType::Int8   | NumpyDType::Int16
            | NumpyDType::Int32  | NumpyDType::Int64 => true,

            // Floats and complex are assumed to cover all integers here
            NumpyDType::Float16 | NumpyDType::Float32
            | NumpyDType::Float64
            | NumpyDType::Complex64
            | NumpyDType::Complex128 => true,
        }
    }
}

/// Returns the minimal NumpyDType meeting:
/// 1) It can represent `value`.
/// 2) No smaller‐bit‐width type can represent it.
/// 3) Among same bit‐width, it has the least kind‐order.
pub fn min_scalar_type(value: i8) -> NumpyDType {
    // All types ordered by increasing bit‐width, and within each width
    // by increasing kind‐order (unsigned, signed, float, complex).
    const CANDIDATES: &[NumpyDType] = &[
        NumpyDType::UInt8,
        NumpyDType::Int8,
        NumpyDType::UInt16,
        NumpyDType::Int16,
        NumpyDType::Float16,
        NumpyDType::UInt32,
        NumpyDType::Int32,
        NumpyDType::Float32,
        NumpyDType::UInt64,
        NumpyDType::Int64,
        NumpyDType::Float64,
        NumpyDType::Complex64,
        NumpyDType::Complex128,
    ];

    for &dt in CANDIDATES.iter() {
        if dt.can_represent_value(value) {
            return dt;
        }
    }

    // In practice, this line is unreachable because Complex128
    // can represent every i8.  But Rust wants a fallback.
    NumpyDType::Complex128
}

